      g.save(); g.translate(0,0); g.fillStyle=S.trim; g.beginPath(); g.moveTo(ax-6, ay+ah+5); g.lineTo(ax-6, ay+r); g.arc(ax+r, ay+r, r+6, Math.PI, 0); g.lineTo(ax+aw+6, ay+ah+5); g.closePath(); g.fill(); g.restore();
      const rr = Math.random();
