      if (Math.random()<.5){ g.fillStyle=`rgba(${190+Math.random()*60|0},${150+Math.random()*80|0},${120+Math.random()*80|0},.9)`; g.fillRect(wx,wy,ww*.35,wh); g.fillRect(wx+ww*.65,wy,ww*.35,wh); }
