    const sh = g.createLinearGradient(0, y + 12, 0, y + 30); sh.addColorStop(0, 'rgba(0,0,0,.35)'); sh.addColorStop(1, 'rgba(0,0,0,0)'); g.fillStyle = sh; g.fillRect(x, y + 12, w, 18);
