        si[i*4] = idx.upperLegL; si[i*4+1] = idx.upperLegR; si[i*4+2] = idx.lowerLegL; si[i*4+3] = idx.lowerLegR;
        sw[i*4] = (1 - u) * s; sw[i*4+1] = (1 - u) * (1 - s); sw[i*4+2] = u * s; sw[i*4+3] = u * (1 - s);
