  if (move === 'strike'){ const C = CLIPS[o.clip]; if (!C) return false; const A = R.anim || (R.anim = {}); A.name = o.clip; A.move = 'strike'; applyClip(R, C, clamp(o.ct, 0, C.dur), o.mirror); return true; }
