    if (n.fightT <= 0 || d > 25 || hero.veh){ const bp = perimPos(n.blk || blocksInfo[n.block] || blocksInfo[0], n.t); n.state = 'goto'; n.tx = bp[0]; n.tz = bp[1]; n.onArrive = n2 => { n2.state = 'walk'; }; }
