  if (n.circ === undefined){ n.circ = Math.random() < .5 ? 1 : -1; n.ringR = 2.6 + Math.random() * .8; }
  let mx = 0, mz = 0; const ux = dx / d, uz = dz / d;
  const far = d > n.ringR + .5, near = d < n.ringR - .4;
