      edgeAt(q.e, q.s, o); const px = q.x, pz = q.z, toward = (f.x - px) * o.fx + (f.z - pz) * o.fz > 0 ? 1 : -1, yaw = Math.atan2(o.fx * toward, o.fz * toward);
      if (Math.hypot(px - f.x, pz - f.z) < minR * .75 || !inWorld(px, pz)) continue;
