      if (onScreen(px, pz) && Math.hypot(px - f.x, pz - f.z) < 150 && lineOfSight(heroAt().x, heroAt().z, px, pz)) continue;
      if (vehBlockedAt(px, pz, 2.6) || staticBlocked(px, pz, 1.6)) continue;
