  for (let i = 0; i < 18; i++){ const g = new THREE.IcosahedronGeometry(R(2, 3), 0); g.translate(x + R(-w / 2, w / 2), 4.6, z + R(-d / 2, d / 2)); p.push(colored(g, '#4b453c')); }
