  for (const n of npcs){ if ((n.state !== 'down' && n.state !== 'dead') || !n.g.visible || n.fly) continue; const d = Math.hypot(n.g.position.x - p.x, n.g.position.z - p.z); if (d < bd){ bd = d; best = n; } }
