  const d = m ? makeDoll3D(cloneRig(MODELS3D[m]), CH.hero, 1.8) : makeDoll(CH.hero, 1.8); d.root.visible = false;
  if (d.R) d.R.mesh.castShadow = GFX !== 'low';
