  npcs.forEach(n => { if (n.thug) npcTakeOff3D(n); n.state = 'hidden'; n.g.visible = false; n.role = null; n.onArrive = null; n.thug = false; n.thugDone = false; n.mhp = undefined; n.mel = false; n.fstyle = undefined; n.g.rotation.x = 0; });
