    if (typeof missionMark !== 'undefined' && missionMark.visible){ const p = missionMark.position; L.push({ x: p.x, y: 3.2, z: p.z, ic: 'star', name: '', mission: true, dd: Math.hypot(p.x - f.x, p.z - f.z) }); }
